import { Group, Mesh, ExtrudeGeometry, Shape, PointLight, SRGBColorSpace } from 'three/webgpu';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec3,
  float,
  dot,
  normalWorld,
  positionWorld,
  cameraPosition,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'hub-collection-badge';

  // ---- capsule shape geometry (rounded pill, small extrusion for real depth) ----
  const w = 1.4;
  const h = 0.42;
  const r = h / 2;

  const shape = new Shape();
  shape.moveTo(-w / 2 + r, -h / 2);
  shape.lineTo(w / 2 - r, -h / 2);
  shape.absarc(w / 2 - r, 0, r, -Math.PI / 2, Math.PI / 2, false);
  shape.lineTo(-w / 2 + r, h / 2);
  shape.absarc(-w / 2 + r, 0, r, Math.PI / 2, (Math.PI * 3) / 2, false);

  const geometry = new ExtrudeGeometry(shape, {
    depth: 0.055,
    bevelEnabled: true,
    bevelThickness: 0.012,
    bevelSize: 0.012,
    bevelSegments: 3,
    curveSegments: 16,
  });
  geometry.center();

  // ---- material: machined-metal-adjacent PBR capsule with fresnel accent rim ----
  const material = new MeshPhysicalNodeMaterial({
    color: colors.ink,
    roughness: 0.55,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });

  // fresnel-based accent edge light baked into emissive node (works regardless of scene lights)
  const viewDir = cameraPosition.sub(positionWorld).normalize();
  const fresnel = float(1.0)
    .sub(dot(normalWorld.normalize(), viewDir))
    .clamp(0.0, 1.0)
    .pow(2.4);
  const accentColorNode = vec3(
    ...new THREE.Color(colors.accent).toArray()
  );
  material.emissiveNode = accentColorNode.mul(fresnel).mul(1.3);

  // subtle grain map on the top face via uv passthrough (kept simple/cheap)
  material.colorNode = vec3(
    ...new THREE.Color(colors.ink).toArray()
  ).add(vec3(0.03, 0.03, 0.035).mul(uv().y));

  const mesh = new Mesh(geometry, material);
  mesh.name = 'badge-capsule-mesh';
  group.add(mesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      material.map = tex;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- accent rim light (node-local, capped) ----
  const rimLight = new PointLight(new THREE.Color(colors.accent), 0.9, 3.0, 2.0);
  rimLight.position.set(0.0, 0.05, -0.5);
  group.add(rimLight);

  // ---- text content (bridging idiom) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  for (const item of items) {
    if (!item?.text) continue;
    const t = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 22,
      color: colors.paper,
      align: 'center',
    });
    t.position.set(0, 0, 0.05);
    group.add(t);
    textNodes.push(t);
  }

  // ---- idle: single slow breathing transform (<=2%) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(mesh.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 2.6,
    ease: 'sine.inOut',
  });

  const timelines = [idleTl];
  const baseY = 0;

  // ---- interaction handlers ----
  const onPointerOver = () => {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    tl.to(
      group.scale,
      { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' },
      0
    );
    tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0.35);
    timelines.push(tl);
  };

  const onPointerOut = () => {
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out',
    });
    timelines.push(tl);
  };

  const onPointerDown = () => {
    const tl = gsap.timeline();
    tl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    tl.to(group.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    timelines.push(tl);
  };

  const onClick = () => {
    ctx.emit('hub-collection.select', { source: 'hub-collection-badge' });
  };

  group.userData.handlers = {
    onPointerOver,
    onPointerEnter: onPointerOver,
    onPointerOut,
    onPointerLeave: onPointerOut,
    onPointerDown,
    onClick,
  };

  group.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    idleTl.kill();
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    for (const t of textNodes) {
      if (t.geometry) t.geometry.dispose();
      if (t.material) t.material.dispose();
    }
    group.remove(rimLight);
  };

  return group;
}
